style.css:
button {
  background: linear-gradient(45deg, #ff6b6b, #556270);
  color: white;
  font-size: 16px;
  padding: 12px 24px;
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.3s ease-in-out;
  position: relative;
  overflow: hidden;
}

button:hover {
  background: linear-gradient(45deg, #556270, #ff6b6b);
  transform: scale(1.1);
  box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);
}
